using Forge.LiveDirector.Authoring;
using Forge.Network.Operations;
namespace Forge.LiveDirector.Tests; public sealed class LiveDirectorNarrativeProfileTests { [Fact] public void R130_QuestsAndEncounters_AreGoverned() { var p = LiveDirectorNarrativeProfile.CreateDefault(); Assert.True(p.QuestInspection && p.ConsequencePreview && p.QuestRuntimeAdapter); Assert.Equal(2, p.QuestScopes.Count); Assert.Equal(5, p.EncounterActions.Count); Assert.True(p.BoundedScaling && p.CreatureSpawnAdapter && p.AiRuntimeAdapter); Assert.Empty(LiveDirectorNarrativeValidator.Validate(p)); } [Fact] public void R130_TransactionRoundTripRuntimeScripts() { var i = LiveDirectorNarrativeProfile.CreateDefault(); var c = i with { ServerRevision = 1, BoundedScaling = true }; var h = new LiveDirectorNarrativeHistory(i); var q = new LiveDirectorNarrativeCommand(Guid.NewGuid(), 1, "test", 0, "gm", NetworkRole.GameMaster, false, c); Assert.False(h.Execute(q).Applied); Assert.True(h.Execute(q with { Apply = true }).Applied); Assert.Equal(i, h.Undo("gm", NetworkRole.GameMaster).Profile); Assert.Equal(c, h.Redo("gm", NetworkRole.GameMaster).Profile); var s = new LiveDirectorNarrativeStore(); Assert.Equal(s.Serialize(c), s.Serialize(s.Deserialize(s.Serialize(c)))); Assert.Empty(LiveDirectorNarrativeRuntimeAdapter.Resolve(null, false).Diagnostics); Assert.Equal("LIVE_NARRATIVE_REQUIRED_MISSING", Assert.Single(LiveDirectorNarrativeRuntimeAdapter.Resolve(null, true).Diagnostics).Code); Assert.Equal(5, new LiveDirectorNarrativeScriptService(i).Read(new(i.Id, 1)).EncounterActions); } [Fact] public void R130_InvalidPermissionRevision_Localized() { var i = LiveDirectorNarrativeProfile.CreateDefault(); var b = i with { ServerRevision = 1, AiRuntimeAdapter = false }; Assert.Contains(LiveDirectorNarrativeValidator.Validate(b), x => x.Code == "LIVE_ENCOUNTER_POLICY_INVALID"); var r = new LiveDirectorNarrativeHistory(i).Execute(new(Guid.NewGuid(), 1, "test", 9, "p", NetworkRole.Player, true, b)); Assert.Contains(r.Diagnostics, x => x.Code == "LIVE_NARRATIVE_PERMISSION_DENIED"); Assert.Contains(r.Diagnostics, x => x.Code == "LIVE_NARRATIVE_REVISION_STALE"); } }
